import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public class Main {
    static int passed, failed;
    static boolean prototype;
    interface Checked { void run() throws Exception; }
    static void test(String name, Checked body) {
        try { body.run(); passed++; System.out.println("PASS " + name); }
        catch (Throwable error) { failed++; System.out.println("FAIL " + name + ": " + error); }
    }
    static void eq(Object actual, Object expected) {
        if(actual instanceof Map<?,?> a && expected instanceof Map<?,?> b && !new ArrayList<>(a.keySet()).equals(new ArrayList<>(b.keySet()))) throw new AssertionError("map key order differs");
        if (!Objects.deepEquals(actual, expected)) throw new AssertionError("expected " + show(expected) + ", got " + show(actual));
    }
    static String show(Object value) { return Arrays.deepToString(new Object[]{value}); }
    static void yes(boolean condition) { if (!condition) throw new AssertionError("condition was false"); }
    static void error(Class<? extends Throwable> kind, Checked body) throws Exception {
        try { body.run(); } catch (Throwable e) { if (kind.isInstance(e)) return; throw new AssertionError("expected " + kind.getSimpleName() + ", got " + e,e); }
        throw new AssertionError("expected " + kind.getSimpleName());
    }
    @SafeVarargs static <T> List<T> list(T... values) { return new ArrayList<>(Arrays.asList(values)); }
    static <K,V> Map<K,V> map(Object... values) {
        Map<K,V> result=new LinkedHashMap<>();
        for(int i=0;i<values.length;i+=2) { @SuppressWarnings("unchecked") K k=(K)values[i]; @SuppressWarnings("unchecked") V v=(V)values[i+1]; result.put(k,v); }
        return result;
    }
    static void suites() throws Exception {
        test("old minimum increases", () -> { long[] a0=new long[]{1L,5L}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,2L),new Exercise.Update("set",0,9L),new Exercise.Update("min",0,2L),new Exercise.Update("min",1,1L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(1L,5L,(Long)null)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("empty values", () -> { long[] a0=new long[]{}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,0L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list((Long)null)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 0", () -> { long[] a0=new long[]{-8L,7L,2L,-2L,-6L,2L,-9L,2L}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,1L),new Exercise.Update("set",0,0L),new Exercise.Update("min",0,5L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,4L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,0L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,5L),new Exercise.Update("set",0,1L),new Exercise.Update("set",0,8L),new Exercise.Update("min",0,5L),new Exercise.Update("set",0,1L),new Exercise.Update("min",0,7L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,2L),new Exercise.Update("set",0,7L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,5L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-8L,-6L,-9L,-2L,-2L,-2L,-6L,-9L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 1", () -> { long[] a0=new long[]{0L,4L,8L,-1L,-7L,-1L,-1L,0L}; List<Exercise.Update> a1=list(new Exercise.Update("set",0,3L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,3L),new Exercise.Update("min",0,4L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,0L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,0L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,1L),new Exercise.Update("set",0,4L),new Exercise.Update("set",0,6L),new Exercise.Update("min",0,7L),new Exercise.Update("min",0,0L),new Exercise.Update("set",0,3L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,8L),new Exercise.Update("min",0,4L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-1L,-7L,(Long)null,(Long)null,-7L,-7L,(Long)null,-7L,-1L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 2", () -> { long[] a0=new long[]{-3L,-2L,-1L,5L,-4L,-7L,3L,-5L}; List<Exercise.Update> a1=list(new Exercise.Update("set",0,4L),new Exercise.Update("set",0,5L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,5L),new Exercise.Update("set",0,6L),new Exercise.Update("min",0,2L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,7L),new Exercise.Update("set",0,7L),new Exercise.Update("set",0,2L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,7L),new Exercise.Update("min",0,6L),new Exercise.Update("min",0,2L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,4L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-7L,-2L,-7L,-2L,-7L,-7L,-2L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 3", () -> { long[] a0=new long[]{5L,-7L,-8L,7L,1L,0L,4L,6L}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,5L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,0L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,1L),new Exercise.Update("set",0,4L),new Exercise.Update("set",0,5L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,7L),new Exercise.Update("min",0,8L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,5L),new Exercise.Update("min",0,6L),new Exercise.Update("min",0,7L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,8L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,7L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-8L,(Long)null,-8L,2L,2L,-8L,-8L,-8L,-8L,-8L,-8L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 4", () -> { long[] a0=new long[]{1L,-3L,2L,8L,-1L,6L,-9L,5L}; List<Exercise.Update> a1=list(new Exercise.Update("set",0,0L),new Exercise.Update("min",0,3L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,2L),new Exercise.Update("set",0,1L),new Exercise.Update("set",0,3L),new Exercise.Update("min",0,5L),new Exercise.Update("set",0,7L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,4L),new Exercise.Update("set",0,3L),new Exercise.Update("min",0,0L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,4L),new Exercise.Update("min",0,3L),new Exercise.Update("set",0,0L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,1L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-3L,-3L,-3L,(Long)null,-3L,-3L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 5", () -> { long[] a0=new long[]{-7L,8L,7L,3L,3L,0L,-4L,-2L}; List<Exercise.Update> a1=list(new Exercise.Update("set",0,3L),new Exercise.Update("set",0,0L),new Exercise.Update("min",0,2L),new Exercise.Update("set",0,0L),new Exercise.Update("min",0,5L),new Exercise.Update("min",0,5L),new Exercise.Update("set",0,5L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,1L),new Exercise.Update("set",0,5L),new Exercise.Update("min",0,8L),new Exercise.Update("set",0,5L),new Exercise.Update("set",0,8L),new Exercise.Update("min",0,3L),new Exercise.Update("set",0,4L),new Exercise.Update("min",0,4L),new Exercise.Update("min",0,2L),new Exercise.Update("set",0,0L),new Exercise.Update("set",0,8L),new Exercise.Update("min",0,7L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(0L,0L,0L,2L,-4L,7L,3L,4L,-4L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 6", () -> { long[] a0=new long[]{3L,1L,-6L,7L,0L,-2L,5L,-7L}; List<Exercise.Update> a1=list(new Exercise.Update("set",0,5L),new Exercise.Update("set",0,3L),new Exercise.Update("min",0,4L),new Exercise.Update("min",0,5L),new Exercise.Update("min",0,4L),new Exercise.Update("min",0,8L),new Exercise.Update("set",0,8L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,2L),new Exercise.Update("set",0,1L),new Exercise.Update("min",0,0L),new Exercise.Update("min",0,1L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,6L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,0L),new Exercise.Update("min",0,2L),new Exercise.Update("min",0,7L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-6L,-6L,-6L,-7L,-7L,-7L,8L,1L,(Long)null,1L,-7L,(Long)null,1L,-6L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 7", () -> { long[] a0=new long[]{7L,8L,-2L,3L,-1L,3L,-4L,2L}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,0L),new Exercise.Update("min",0,8L),new Exercise.Update("set",0,1L),new Exercise.Update("min",0,3L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,1L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,1L),new Exercise.Update("set",0,8L),new Exercise.Update("set",0,7L),new Exercise.Update("min",0,3L),new Exercise.Update("min",0,3L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,6L),new Exercise.Update("min",0,0L),new Exercise.Update("min",0,1L),new Exercise.Update("set",0,2L),new Exercise.Update("set",0,4L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list((Long)null,-4L,-2L,-4L,1L,-2L,-2L,-2L,-2L,(Long)null,6L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 8", () -> { long[] a0=new long[]{-7L,7L,-4L,-1L,-8L,-7L,3L,1L}; List<Exercise.Update> a1=list(new Exercise.Update("set",0,5L),new Exercise.Update("min",0,5L),new Exercise.Update("min",0,4L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,7L),new Exercise.Update("min",0,4L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,1L),new Exercise.Update("min",0,7L),new Exercise.Update("set",0,1L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,3L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,6L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,7L),new Exercise.Update("set",0,2L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-8L,-4L,-4L,-4L,-4L,-8L,-8L,-4L,2L,-8L,2L,-8L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 9", () -> { long[] a0=new long[]{0L,-8L,7L,-2L,-6L,-1L,1L,-1L}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,3L),new Exercise.Update("min",0,5L),new Exercise.Update("set",0,1L),new Exercise.Update("set",0,3L),new Exercise.Update("set",0,7L),new Exercise.Update("min",0,0L),new Exercise.Update("set",0,1L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,5L),new Exercise.Update("set",0,1L),new Exercise.Update("set",0,8L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,1L),new Exercise.Update("set",0,0L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,0L),new Exercise.Update("min",0,3L),new Exercise.Update("set",0,4L),new Exercise.Update("set",0,6L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-8L,-8L,(Long)null,1L,-8L,2L,2L,(Long)null,-8L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 10", () -> { long[] a0=new long[]{8L,-3L,-2L,-2L,5L,5L,4L,-7L}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,2L),new Exercise.Update("min",0,3L),new Exercise.Update("min",0,0L),new Exercise.Update("set",0,8L),new Exercise.Update("min",0,5L),new Exercise.Update("min",0,6L),new Exercise.Update("set",0,5L),new Exercise.Update("set",0,6L),new Exercise.Update("min",0,5L),new Exercise.Update("min",0,3L),new Exercise.Update("set",0,2L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,0L),new Exercise.Update("set",0,0L),new Exercise.Update("set",0,4L),new Exercise.Update("set",0,2L),new Exercise.Update("set",0,0L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,2L),new Exercise.Update("set",0,6L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-3L,-3L,(Long)null,-3L,-3L,-3L,-3L,2L,(Long)null,0L,-3L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("point replacements 11", () -> { long[] a0=new long[]{-3L,0L,-8L,-2L,-6L,6L,5L,-3L}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,3L),new Exercise.Update("min",0,2L),new Exercise.Update("set",0,6L),new Exercise.Update("set",0,0L),new Exercise.Update("min",0,2L),new Exercise.Update("min",0,0L),new Exercise.Update("set",0,7L),new Exercise.Update("set",0,0L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,8L),new Exercise.Update("set",0,8L),new Exercise.Update("set",0,7L),new Exercise.Update("min",0,8L),new Exercise.Update("min",0,7L),new Exercise.Update("set",0,8L),new Exercise.Update("min",0,4L),new Exercise.Update("set",0,1L),new Exercise.Update("min",0,1L),new Exercise.Update("min",0,7L),new Exercise.Update("set",0,2L)); String before=show(new Object[]{a0,a1}); try { eq(prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1),list(-8L,-3L,0L,(Long)null,0L,-8L,-8L,-8L,-8L,1L,-8L)); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("invalid input", () -> { long[] a0=new long[]{1L}; List<Exercise.Update> a1=list(new Exercise.Update("set",1,2L)); String before=show(new Object[]{a0,a1}); try { error(IllegalArgumentException.class, () -> { Object ignored = prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1); }); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("invalid input", () -> { long[] a0=new long[]{1L}; List<Exercise.Update> a1=list(new Exercise.Update("min",0,2L)); String before=show(new Object[]{a0,a1}); try { error(IllegalArgumentException.class, () -> { Object ignored = prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1); }); } finally { eq(show(new Object[]{a0,a1}),before); } });
        test("invalid input", () -> { long[] a0=new long[]{1L}; List<Exercise.Update> a1=list(new Exercise.Update("add",0,2L)); String before=show(new Object[]{a0,a1}); try { error(IllegalArgumentException.class, () -> { Object ignored = prototype ? Exercise.prototype(a0,a1) : Exercise.solve(a0,a1); }); } finally { eq(show(new Object[]{a0,a1}),before); } });

        if(!prototype) test("final scale and structure boundary", () -> { long[] a=new long[10000];Arrays.fill(a,100);List<Exercise.Update> c=new ArrayList<>();for(int i=0;i<a.length;i++)c.add(new Exercise.Update("set",i,i));c.add(new Exercise.Update("min",0,10000));c.add(new Exercise.Update("set",0,10000));c.add(new Exercise.Update("min",0,10000));c.add(new Exercise.Update("min",0,0));eq(Exercise.solve(a,c),list(0L,1L,null));eq(a[0],100L); });
    }
    public static void main(String[] args) throws Exception {
        String stage="final";
        if(args.length!=0) {
            if(args.length!=2 || !args[0].equals("--stage")) { System.err.println("Usage: java Main --stage prototype|final"); System.exit(2); }
            stage=args[1];
        }
        if(!stage.equals("prototype") && !stage.equals("final")) { System.err.println("Unknown stage: " + stage); System.exit(2); }
        prototype=stage.equals("prototype"); suites();
        System.out.println("RESULT stage="+stage+" passed="+passed+" failed="+failed);
        if(failed>0 || passed==0) System.exit(1);
    }
}
